<!doctype html><html><head><meta charset="utf-8"><title>Invoice {{ $folio->folio_number }}</title><link rel="stylesheet" href="{{ asset('css/hms.css') }}"></head><body class="print-page"><div class="print-toolbar"><button onclick="window.print()" class="btn primary">Print invoice</button><button onclick="window.close()" class="btn">Close</button></div><article class="document"><header><div><h1>INVOICE</h1><b>{{ $folio->property->name }}</b><p>{{ $folio->property->address }}<br>{{ $folio->property->phone }} · {{ $folio->property->email }}<br>TIN: {{ $folio->property->tin }}</p></div><div class="doc-meta"><b>{{ $folio->folio_number }}</b><span>Date {{ now()->format('d M Y') }}</span><span>Reservation {{ $folio->reservation?->reference }}</span></div></header><section class="bill-to"><small>BILL TO</small><b>{{ $folio->guest->full_name }}</b><span>{{ $folio->guest->phone }} {{ $folio->guest->email }}</span></section><table><thead><tr><th>Description</th><th>Qty</th><th>Unit Price</th><th>Tax</th><th>Total</th></tr></thead><tbody>@foreach($folio->items as $i)<tr><td>{{ $i->description }}<small>{{ ucwords($i->department) }}</small></td><td>{{ $i->quantity }}</td><td>UGX {{ number_format($i->unit_price) }}</td><td>UGX {{ number_format($i->tax_amount) }}</td><td>UGX {{ number_format($i->total) }}</td></tr>@endforeach</tbody></table><div class="doc-totals"><span>Total charges<b>UGX {{ number_format($folio->charges_total) }}</b></span><span>Payments<b>UGX {{ number_format($folio->payments_total) }}</b></span><span class="grand">Balance due<b>UGX {{ number_format($folio->balance) }}</b></span></div><footer>Thank you for choosing {{ $folio->property->name }}.</footer></article></body></html>